import{_ as w,o as t,c as o,j as e,a as r,F as s,B as h,t as i,e as g,k as u}from"./chunks/framework.CGSzHL4z.js";const y=JSON.parse(`[{"version":"0.20.0","date":"2026-10-30","name":"Working together","Notes":["**See your teammates while you animate**: In Team Create, everyone with AcesMotion sees each other. Avatars sit on the Timeline toolbar, each teammate gets a playhead and a name flag on the ruler in their own colour, and what they pick shows as rings on keys, stripes on rows and their joints in the viewport with a name tag. While someone types in or drags an Inspector field, that row shows their colour and avatar. Nothing extra is saved into the place.","**Follow a teammate**: Click a teammate's avatar to put your camera and playhead on theirs. When they play, you play with them, sounds and effects included, and a teammate in another scene opens that scene first. Move the camera, scrub, pick something or press Play and you take back control, with a Follow button to pick up again. A chip in the viewport tells you who is following you. Studio's own Team Create camera marker for the person you follow still shows; it can't be hidden yet.","**Edit the same scene at the same time**: Two people can change the same actor at once and both changes stay: yours is applied again on top of theirs in the same undo step. Keys a teammate is dragging show a lock, but you can still move them, and whoever lets go last wins. Ctrl+Z only undoes your own steps, and if it would wipe a teammate's change you get Put back to restore theirs. Changing the frame rate or restoring a version asks first and names who is in the scene.","**Settings for working together**: Settings > Collaboration, the View menu and every teammate menu turn teammates' playheads, selections and the viewing chip on or off, only on your screen. People show by their display name.","**A Scenes tab built for big places**: Scenes now remember who made them and who edited them last. The Hub's Scenes tab groups them by the folders under AcesMotionScenes (or by creator), with collapsible groups, search by name or person, chips for Mine, Recent and In this session, a Made by filter and sorting. Make folders, rename them, drag scenes between them and move scenes kept elsewhere into AcesMotionScenes. It stays quick with a thousand scenes or more, and the Timeline's Scene field opens a picker of the same list.","**Resize limbs and key their size**: The Resize tool now works on the limbs of Motor6D and AnimationConstraint rigs. A limb grows away from the joint it hangs from, and the joints inside it move out with it, so a longer upper arm carries the forearm and hand down at their own size. Hats, hair and welded parts on it move out too. Flip pose, mirrored paste and the pose library carry limb sizes. Only the AcesMotion runtime plays them, since a Roblox animation can't hold part sizes. Bones can't resize.","**See which posing tool is on**: A small pill at the viewport's bottom left names the posing tool, Move and rotate or Resize, and turns amber with the reason when nothing picked can resize. Click it to switch, or right-click it for the handle options. Hide it from its menu, the View menu or Settings > Posing."],"Improved":["**New defaults: Auto-key on, Onion skin and Trajectory off**: New installs start with Auto-key on, and with Onion skin and the motion trail off. Settings you changed yourself stay as they were.","**A redrawn scene icon**"],"Fixed":[]},{"version":"0.19.2","date":"2026-10-29","name":"Replayed moves off screen","Notes":[],"Improved":[],"Fixed":["**Moves played again and again stay culled off screen**: A new play counted as on screen until its first visibility check, up to a quarter second later, so an off-screen rig replaying an attack every third of a second still posed most frames. Each play now checks on its first frame: off screen it never poses, on screen it poses every frame as before."]},{"version":"0.19.1","date":"2026-10-29","name":"Off-screen rigs with Locks","Notes":[],"Improved":[],"Fixed":["**Rigs with foot Locks stop posing off screen**: A rig whose stack had a Lock or a Floor posed every frame in games, even off screen, so a crowd of units cost as much as if all were in view. Constraints aimed at the rig itself, or at a spot in the scene, now follow level of detail like the rest of the rig. Markers and Event blocks still fire on time. A driver, a custom constraint or one aimed at another role still keeps it posing every frame."]},{"version":"0.19.0","date":"2026-10-29","name":"Timing on the server clock","Notes":["**Read marker times without playing**: AcesMotion.GetMarkers, GetEvents, GetMarkerTime and GetLength tell your game when a scene's markers and Event blocks fire and how long it plays, on the server or a client, from a scene or a reference. A combat move can look up its Hit time before the swing starts instead of keeping a copy in an attribute.","**Time maps on the server clock**: Track:SetTimeMap, or the TimeMap play option, ties a track's time to server time with a few knots. The track speeds up or slows down to reach each one, so a hit lands exactly when the server says. Markers fire once as the time crosses them, and every client, late joiners too, shows the same frame."],"Improved":[],"Fixed":[]},{"version":"0.18.2","date":"2026-10-29","name":"Smoother fades","Notes":[],"Improved":[],"Fixed":["**Arms no longer swing over the head in a fade**: When one scene fades into another, a joint set to Each angle on its own now moves angle by angle, the way its keys do. Going from a raised guard idle to a run used to swing the arm straight up for a few frames."]},{"version":"0.18.1","date":"2026-10-29","name":"Cleaner rotations","Notes":["**See where Shortest turn is off**: A warning icon on a joint's row says where its turn falls back to each angle on its own, and why. Click it, or open Between keys in the row, key or Inspector menus, to fix it: Align keys gives every angle a key where one has, and Unwind turns a spin into the short way."],"Improved":["**Keys store angles that suit their neighbours**: Posing, pasting and mirroring a pose pick the angles that fit the keys before and after it, so the curves stay smooth and the graph shows fewer flips. The Euler filter also straightens poses stored the other way round, not just whole turns."],"Fixed":["**No more swinging past key poses**: With Between keys set to Shortest turn, a joint that reaches an extreme and comes back (every run cycle) used to swing up to 65 degrees past the key pose. The turn is now flat at those keys and never overshoots, like Auto tangents on a curve. Linear and Flat keys don't bend at all, and Smooth keys keep the old free curve. Games get the same motion.","**Near-identical poses don't spin round**: Two keys only a few degrees apart could spin almost a full turn when their angles were stored a turn or a flip apart. They now turn the short way. A real spin, one angle past 180 degrees with the others nearly still, still spins.","**Flip pose and Reset work from the Timeline**: Shift+F and Shift+R only worked with the viewport focused. They now work from the Timeline, Hub and the Inspector too, and with keys on joint rows selected in the Timeline they flip or reset those keys' joints at the playhead, in one undo step.","**Paste keys mirrored moves locked parts**: Pasting keys mirrored onto a joint with a Lock changed nothing: the lock held the part where it was. The lock now follows, keyed where the mirrored pose puts the part. Pasting keys from an unlocked joint onto a locked one does the same.","**Joint keys paste only onto the same joint**: Keys copied from a joint pasted onto a rig that doesn't have it, or onto whatever joint row was selected. They now go only onto the joint of the same name (its partner for Paste keys mirrored). Joints the rig doesn't have are skipped and a toast names them; if none are there, nothing is pasted.","**Copy pose and Flip read the keyed pose**: On a locked or constrained joint, Copy pose, Flip pose and Save pose took the constraint's result instead of the joint's own pose, so Paste mirrored in the viewport and Paste keys mirrored in the Timeline gave different keys. Both now give the same."]},{"version":"0.18.0","date":"2026-10-29","name":"Scene anchors","Notes":["**Scene origin can follow a role**: Under Scene origin in the Hub's Cast tab, set Origin to Follows and pick the role whose part the scene rides in a game, and which part (HumanoidRootPart by default). AcesMotion.Load(clip, model) then plays a punch effect on whoever throws the punch, with no Anchor in your code. The viewport shows the scene riding that role's stand-in, so it plays where you see it.","**References can pick their own origin**: A reference's Origin field in the Inspector uses the scene's setting, plays where the scene was authored, or follows another role. An Anchor passed in code still wins over both."],"Improved":["**One Scene origin group**: Relative to is now Characters move from (Own root part, Scene origin, Mixed), and the origin's place is one Origin setting: Where authored or Follows. Spawned actor rows say what they follow, such as follows Unit > Torso.","**First anchor filled in for you**: When a scene with one character gets its first spawned actor key, the scene is anchored to that character in the same undo step, and a toast says so with a Clear button. Clearing it keeps it cleared. Existing scenes are left alone.","**More numbers on the seconds ruler**: In seconds, the ruler labels as densely as it does in frames: zoomed in on a 2 s scene it reads 0.1s, 0.2s, 0.3s instead of every half second. Labels drop trailing zeros, like 0.25s and 1s.","**Anchors work for everyone**: PlayForAll, server plays and late joiners use the same anchor. A client finds the role's part on its own side when the character streams in or the cast changes."],"Fixed":["**Part pickers in the Hub**: Socket, Parent to and the origin's Part picker in the Hub's Cast tab open their list again. Before, the list only ever drew in the Inspector."]},{"version":"0.17.0","date":"2026-10-28","name":"References manager","Notes":["**References window**: A table of every reference in the place, grouped by name, scene or owner. Point many references at a scene at once, fix ones whose scene or cast is gone, rename a move everywhere, and add references to many models. Picking rows selects the references in Studio, and the other way round.","**References toolbar button**: A third toolbar button opens the References window. It is also in View > Windows, in the Hub's Scenes tab, in the reference panel, and on a shortcut you can bind.","**Re-reference clips from the Explorer**: Select references and one scene, then click Create reference to point them at that scene. Their names stay, so code that plays them by name keeps working. Cast entries for roles the new scene doesn't have are removed, and the toast says how many.","**References go into any instance**: Create reference puts one into each selected instance of any class, such as a folder or a part, not only models. A target that already has one with that name gets a numbered copy, like BasicAttack2."],"Improved":["**Clip counts in the Hub**: Each scene in the Scenes tab shows how many references play it; click the count to see them in the References window. When you delete a scene that references use, the question turns orange and says how many.","**Reference docs are easier to read**: The reference pages use tables, short headings and key labels instead of long lists."],"Fixed":[]},{"version":"0.16.0","date":"2026-10-28","name":"Clip references","Notes":["**References you clone into NPCs**: A reference is a small Configuration that points at a scene by its id. Clone it into each NPC or its template, the way you would an Animation, and play it with AcesMotion.Play(npc, \\"Punch\\"). Renaming or moving the scene doesn't break it.","**Cast each role on the reference**: A reference can name who plays each role, with an Instance attribute named after the role. A target inside the same model follows the model into every clone. Roles you leave empty play your code's cast, else the actor's fallback.","**Create reference button**: A second toolbar button makes a reference to the scene selected in the Explorer: one in each selected model, or one in ReplicatedStorage to drag where you need it. It's also in the Scene menu and on each scene in the Hub.","**Reference panel in the Inspector**: Select a reference to see its scene, role and cast, point it at another scene, or open its scene. An empty cast field says what plays the role instead, such as the fallback."],"Improved":["**Scenes found by id**: A reference finds its scene by id in the scene folders and anywhere a scene is tagged, so scenes can live outside AcesMotionScenes. If two scenes share an id, the runtime warns once.","**Plays don't depend on scene names**: Relayed client plays and late joiners find the scene by its id, so a renamed scene still plays for everyone."],"Fixed":[]},{"version":"0.15.4","date":"2026-10-28","name":"Windows and viewport picks","Notes":[],"Improved":["**Socket and Parent to use the part picker**: In the Inspector and the Cast tab, both fields get the same picker as Attached to: a searchable list of the cast's parts, a viewport pick, Use selection and right click Clear.","**Spawn and Camera sections scroll**: They scroll with the properties, so a long Spawn section no longer pushes the rest off screen. Only the object picker and Search properties stay at the top.","**Studio shortcut bindings explained**: Settings > Shortcuts says that every command is also in Studio's Customize Shortcuts, and that a key bound there works even while you type, so pick one with Ctrl or Alt."],"Fixed":["**Every window opens after an update**: Updating or reloading AcesMotion while Studio was open could leave some windows unbuilt, starting with the Inspector. Each window now replaces any leftover copy from before the update.","**Viewport picks stay on what you're picking**: Picking a Socket, Parent to or Attached to part in the viewport no longer selects that part in Studio and moves the Inspector away. A chip in the viewport says what you're picking, and pressing the pick button again cancels.","**Space plays from the viewport**: Space plays and pauses with the viewport, Hub or the Inspector focused, not only the Timeline. It does nothing while you type or with no scene open."]},{"version":"0.15.3","date":"2026-10-28","name":"Vanishing joints fix","Notes":[],"Improved":[],"Fixed":["**Joints no longer vanish between keys**: In 0.15.2, two keys with almost the same rotation could break a joint's rotation between them, and the part disappeared. The joint now stays put for that tiny turn, and no key is ever saved with a broken value."]},{"version":"0.15.2","date":"2026-10-28","name":"Shortest turns and multi-select","Notes":["**Pick several things and change them all at once**: Ctrl+click or Shift+click layers, versions, scenes, markers or actors, or Alt+click pose cards. Delete, duplicate, mute, recolour or move them in one undo step. Shift+drag along the ruler to box select markers.","**Picked parts count as selected rows**: Joints you pick in the viewport take Add constraint, Motion Warp, generator and driver just like their rows, and the viewport's right-click menu has an Add submenu. When a target is needed, you pick it once for all of them.","**Pose tools work on several actors**: Paste pose, Paste mirrored, Flip pose and Reset to rest act on every picked actor at once.","**Between keys: Shortest turn or Each angle on its own**: Set how a rotation track goes from key to key in the row menu, the key menu's Rotation submenu or the Inspector's Key panel. With several rows selected, the row menu sets them all in one undo step.","**A clearer changelog and What's new**: Settings > About > Changelog lists every version with a search, New, Improved and Fixed filters and a card per release. What's new covers everything since the version you last saw."],"Improved":["**X switches between IK and FK**: Press X in the viewport to switch. It stays switched until you press X again, instead of only while you hold I. Mid drag, X still locks the X axis, and a key you rebound before keeps working."],"Fixed":["**Torsos and limbs no longer lift between keys**: When a joint's X, Y and Z keys sit on the same frames, it takes the shortest turn between them, the way Roblox's Animation Editor blends poses. Eases and overshoot still shape it. Camera roots keep each angle on its own curve, so a camera never rolls.","**Windows stay where you put them**: Docked and floating windows keep their place and size when AcesMotion updates or reloads."]},{"version":"0.15.1","date":"2026-10-28","name":"AcesFX property links","Notes":["**Keyed AcesFX settings move their followers**: Keying a setting others follow, such as a Ride time a Duration follows, moves its followers with the link's Scale and Offset while you scrub, play and in games.","**Linked rows show what they follow**: A follower can still be keyed, and its own keys win. Its row shows a link icon, and its tooltips say what it follows."],"Improved":[],"Fixed":[]},{"version":"0.15.0","date":"2026-10-25","name":"AcesFX blocks","Notes":["**AcesFX blocks: Emit, Enable, Disable, Enabled**: Play an actor's AcesFX effects right where they are. Add them from Add block > AcesFX; each targets the whole actor or one part.","**Scrub AcesFX effects frame by frame**: Bursts, streams, riders, lights, beams, lightning, trails, sounds and camera shake show as they play at the frame you're on, forward or back.","**Timing tails behind AcesFX blocks**: Ticks for bursts, a stripe while a part emits, the held band, the wind-down and an end cap. Tail ends and bursts are snap targets.","**AcesFX blocks in the Inspector**: Target, Scale, lightning targets, what it fires and for how long, and Select in AcesFX.","**AcesFX blocks play in games**: Each client plays them through the game's AcesFX runtime, following jumps, loops, SetSpeed and Pause. Effects = false skips them.","**Trails while scrubbing**: On by default. Every Trail draws from where its attachments were while you scrub, pause or play faster than 1x.","**Hide empty rows in pickers**: A filter button beside the search hides greyed out rows. Also in the list's right-click menu and Settings > Look."],"Improved":["**Lighter scrubbing with thousands of particles**: The preview simulates only the particles its cap shows, and rebuilds a moving particle's frozen copy far less often."],"Fixed":[]},{"version":"0.14.3","date":"2026-10-23","name":"One selection for the viewport and Timeline","Notes":["**Esc or an empty click selects nothing**: Clears picked joints, keys, blocks, rows and actors, from the viewport, the lanes or the space under the last row."],"Improved":[],"Fixed":["**Row clicks and viewport picks share one selection**: Clicking a joint's row lets go of the joints picked in the viewport, and the other way round, so old picks no longer stay highlighted.","**Row buttons act on viewport picks**: Stack, Mute, Solo and Lock act on every selected row when the joints are picked in the viewport.","**Stack rows switches every row again**: A row set back by its own stack button follows Stack rows, and switching Stack rows clears the rows' own choices."]},{"version":"0.14.2","date":"2026-10-23","name":"Hide while playing, Stack rows, R6 rigs","Notes":["**Hide while playing**: On by default, in the View menu and Settings > Gizmos: while the scene plays, the gizmo, joint dots, bones, highlights, the trail, guides and camera frustums step aside so you watch the animation alone.","**Stack rows**: A button on the rows header, View, the rows filter menu, Settings > Timeline; each row also has its own stack button beside Mute, to hide one row while it's on or show one row while it's off. Turn it off to hide the generator, constraint and driver lanes under their rows, so you animate keys alone and a box select takes keys only. The blocks keep playing.","**Add constraints and drivers to several rows**: Select several rows and right-click one: Add constraint and Add driver put the pick on every selected row in one undo step, as Add generator already did, with its target picked once for all of them."],"Improved":[],"Fixed":["**Duplicated stack blocks land below the original**: Duplicating a block on a stack row (a generator, constraint or driver) puts the copy in the sub-lane below at the same time, instead of after the scene's end where it couldn't be seen.","**Stack rows fit the lanes their blocks use**: A stack row is as tall as the sub-lanes its blocks use: a lone block moved to a lower lane no longer leaves empty lanes above it.","**IK on custom R6 rigs bends the limb you drag**: IK posing on a custom R6 rig bends the arm or leg you drag instead of swinging the whole body: limbs named without the space (LeftArm, RightLeg) were taken for held props, and moved their holder, the torso. An IK chain set longer than the limb never takes the rig's root joint either.","**Locks hold R6 feet and hands**: A limb that is one joint turns at the hip or shoulder to keep its end on the spot, instead of keeping its angle and sliding with the body.","**Locked feet stay planted at a lock's first frame**: A lock with no Spot yet gets the spot it holds before the pose moves anything, so posing the hips no longer drags it along."]},{"version":"0.14.1","date":"2026-10-23","name":"Scenes in ViewportFrames","Notes":["**Scenes play on rigs in a ViewportFrame**: Such as an inventory card or a reveal. A card is judged by how it shows on screen instead of by the world camera: it rests while hidden, disabled or scrolled out of its list, MaxDistance leaves it alone, and copies the scene spawns stay inside the card."],"Improved":["**Custom modules keep their id under their own attribute**: Custom generators, constraints and drivers use AcesMotion_GeneratorId, AcesMotion_ConstraintId and AcesMotion_DriverId. Modules made earlier keep working; their AcesMotion_ActionId is still read and copied over the next time the plugin touches them.","**A custom action's Scrub error warns in games**: A custom action whose Scrub errors in a game now warns once in Output, as it does in Studio.","**Custom constraint errors warn once**: A custom constraint whose Solve errors or returns no CFrame warns once in Output, like generators and drivers.","**Cast accepts typed lists under strict mode**: AcesMotion.Cast accepts a typed list such as { Model } for a list role under --!strict."],"Fixed":["**NPCs end where players saw them after PlayForAll**: After a PlayForAll, the server puts an NPC where players saw it end, Motion Warp and attach keys included, and a prop the scene carries and drops lands where it was dropped instead of staying behind on the server.","**Camera scenes ignore MaxDistance**: With MaxDistance set, a scene that drives the camera keeps playing however far its anchor is, instead of freezing the view.","**Ease window handles update as you drag**: Dragging a handle in the Ease window updates the curve, the fields and the scene as you drag, not only when you let go.","**Zoomed-out curves no longer draw flat**: Curves no longer draw flat on their zero line when the curve editor is zoomed out to a wide range of values (0 to 100 degrees in a short graph).","**Destroying a Track disconnects every signal**: Destroying a Track also disconnects LengthChanged, CameraAttached, CameraDetached and ShotChanged.","**Custom drivers with no target change nothing**: A custom driver with a required target left unset changes nothing, like the built-in drivers, so the value under it plays.","**Custom generators can have their own Low, High, Speed**: A custom generator can have its own Low, High, Speed or StepRate setting: the Between Low and High, Scroll and Pattern modes keep their values apart from it."]},{"version":"0.14.0","date":"2026-10-23","name":"Screen effects and camera tools","Notes":["**Screen effects**: Add them from the + menu, the Cast tab or the Camera row, then key letterbox bars (top and bottom), a vignette, blur, a fade to any colour, colour correction and bloom. Studio shows them while you look through a camera, and games draw them on the player's screen while a scene has the camera, easing in and out with it.","**Depth of field per camera**: A Lens section with focus distance, Focus on (an actor or part the focus follows), in-focus radius and near and far blur.","**Hold / Fade generator and screen effect presets**: Hold / Fade, a new generator, and Screen effects presets in the Library: Fade to black, Fade from black, Flash white, Letterbox and Vignette pulse. The Screen row's menu adds fades, a flash and letterbox bars at the playhead.","**A fighter's point of view**: Attach a camera to a head from its Camera section and press Eyes. In games it follows the head as it really moves, the game's own animation included.","**Scriptable cameras for games**: Camera = \\"Manual\\" works the scene's camera out without touching the player's, read with GetCamera (its screen effects and lens too), with AttachCamera, DetachCamera and the CameraAttached, CameraDetached and ShotChanged signals.","**Camera in game settings**: Press the Camera row to set how a game's camera glides into the scene and back out, with its own ease, and what happens when the scene is stopped early.","**Reorder actors by dragging**: Drag them in the Cast tab or on the Timeline. A scene can keep its own Timeline order.","**OKLab and OKLCH colour blends**: For colour tracks and the gradient editor: colours fade from one to the next in even, natural steps."],"Improved":["**Cameras turn like a camera head**: The rotate gizmo pans and tilts without rolling, and pans and orbits blend smoothly between keys.","**Tooltips on menu items**: Menu items that don't explain themselves have tooltips.","**Peak sensitivity setting**: Settings > Audio > Peak sensitivity sets how quiet a waveform hit can be and still snap.","**The Sequence editor opens taller**"],"Fixed":["**Cameras no longer tilt or roll between keys**: A camera in a scene that measures root motion from each actor's root part no longer tilts up or rolls between keys, and plays in Studio as it does in games.","**Posing a Lock's target moves the locked part**: Also at the lock's first frame.","**Reset to default on screen effects and lens**: Reset to default works on screen effect and lens values."]},{"version":"0.13.0","date":"2026-10-22","name":"Scene versions, poses and locks","Notes":["**Scene versions**: Alt+Shift+S or the Hub's new History tab saves a version of the scene, and automatic ones are kept as you work, on open and close, before exports and before heavy edits. Preview one read-only, Compare it as a ghost with faint keys while you work, Restore the whole scene or only the selected actors, or Branch it into a new scene.","**A dot marks unsaved changes**: A dot after the scene name marks changes no version you saved holds, in the Timeline, the Hub and the scene lists.","**Toasts show what happened**: Toasts show what happened in the window you work in, with Undo and other actions where they help. Click the status bar's message for the recent ones; Settings > Look sets how long they stay and where.","**Save as names and opens the copy**: Save as asks for the copy's name and opens the copy.","**Pose library**: Save poses for any rig, apply them with a click or a slot key (Alt+1 to Alt+9), blend toward one with an Alt drag, and find one fast with the quick pose picker (Ctrl+Alt+P). Poses are yours and travel with Export presets.","**Locks plant feet and hold hands**: Plant a foot or hold a hand where it is, in the world or on another actor, while the rest of the body moves. Lock between selected keys, Shift+L on a picked part, or turn pins into locks; posing a locked part keys where the lock holds it, so one lock can run the whole timeline. Chain length, Spot only and a viewport marker that turns red when the limb can't reach. Locks play in games and export natively.","**Let the prop lead**: Key a held sword's swing and the arm follows it."],"Improved":["**Bars no longer add main keys**: Constraints, generators, drivers and action blocks no longer add main keys, so a main key moves only keys.","**Copy and paste is context aware**: A copied block pastes onto the selected block or row.","**Export and import presets through ServerStorage**: Export presets puts a folder in ServerStorage and selects it, and Import presets reads the export selected in the Explorer.","**Settings for automatic versions**: Settings > Versions sets automatic versions and how many this place keeps."],"Fixed":["**Keying on a layer keeps the pose you see**: Keying on a layer, or on Base under layers, keeps the pose you see instead of adding the layers above on top of it.","**Keys sit centred on the playhead**: Keys sit centred on the playhead line at every zoom and UI scale.","**Floor measures the pose at its frame**: A Floor on a rig measures its pose at that frame, keeps a locked foot on the floor instead of lifting the rig early, and Bounding box now counts each part's box.","**Blocks dragged past the end come back**: A block dragged past the scene's end can be dragged back."]},{"version":"0.12.0","date":"2026-10-21","name":"Scene layers and a Gizmos page","Notes":["**Scene layers**: Animate on top of Base with Override or Additive layers, each with a keyable Weight, a mask, Mute and Solo. Manage them in the Hub's Layers tab and switch with the toolbar's layer picker; the Timeline shows one layer at a time.","**Posing on a layer saves what you see**: An Additive key holds the difference from the layers below, an Override key the blend that lands on your pose.","**Show other layers, Merge down, Bake to Base**: Show other layers draws the other layers' keys as faint dots for timing. Merge down and Bake to Base fold layers without changing the pose.","**Layers play in games**: Layers play in games as in Studio, and options.Layers or Track:SetLayerWeight fades a layer by name. Native export bakes the layers in.","**A Gizmos page in Settings**: It gathers every gizmo, bone and joint dot setting, with bone colour, thickness and transparency and joint dot colour, size and transparency.","**A colour picker on every colour setting**: Every colour setting has a colour picker: click its swatch."],"Improved":[],"Fixed":["**Turns past 90 degrees keep their axis**: A joint turned past 90 degrees about one axis keeps that turn instead of flipping to a half turn on the other two, so rigs no longer roll between keys. Turns past 180 degrees and whole turns keep going the way they were turned, in keys, bakes, merges, imports and exports."]},{"version":"0.11.0","date":"2026-10-21","name":"Held props, command palette, shortcuts","Notes":["**Held props ride a joint in games**: A part or model attached to a hand costs nothing per frame. Unanchor, Massless and Non-colliding switches in the Attached group say what it is while held, and attaching an anchored prop offers to unanchor it.","**Command palette**: Press F3 to find and run any command, with your recent ones first.","**Rebind every shortcut, search Settings**: Every shortcut can be rebound in Settings, and Settings has a search across all of its pages.","**Viewport right-click menu**: Right click in the viewport for a menu of posing, keying and attach commands.","**Tween slider**: Blend the picked joints between their keys into Breakdowns.","**Solo, and curves before and after their keys**: Solo rows and actors in the editor, and set what a curve does before and after its keys: Hold, Cycle, or Cycle with offset.","**Copy and paste blocks and switch keys**: Copy and paste blocks, Camera switch keys and attach keys. Presets drag from the Library onto Timeline rows.","**More ways to select keys**: Select keys before, after or at the playhead, by key type, or inverted. Selected keys show a Key panel in the Inspector.","**Typed amounts and axis locks on gizmo drags**: Gizmo drags take typed amounts, X, Y and Z axis locks and a Shift fine drag. An Arrow length setting, with shorter arrows by default."],"Improved":["**Easier gizmo hit areas**: The gizmo's hit areas grow with its size, the nearest handle wins, and handles fade out edge-on. Joint dots inside the trackball take the click.","**Overlays drawn like the gizmo**: Viewport dots, trails and guides are drawn like the gizmo, with a faint copy on top, and can show for selected actors only or hide with Hide overlays.","**Alt flips snapping for one drag**: Alt flips snapping for one drag, and frame snapping holds with Snap off. Auto-key on shows in record red.","**Esc cancels drags, undo restores the selection**: Esc or a right click cancels any Timeline drag or viewport pick. Undo and redo bring the selection back, and every undo step is named AcesMotion with what it did.","**Shorter menus with every shortcut named**: Shorter menus, every shortcut named in its menu or tooltip, and Inspector panels remember their folded sections.","**Trail range and animated-only properties**: The trail can show a range around the playhead with a frame tick step, and the property list can show animated properties only.","**Renames reach everything, recovery per scene**: Renaming an actor renames everything that names it, and crash recovery keeps a copy per scene."],"Fixed":["**Delete, Backspace and Esc reach everything**: Delete, Backspace and Esc reach markers, rows and the Inspector, locked keys stay selected with the reason, and removing an actor says what it leaves.","**Tangents keep their shape**: Tangent modes keep Broken shapes, normalised curves hold their fit while dragging, and the graph picks the nearer of a key and a tangent knob.","**Stop at follows the ruler's units**: A sound's Stop at follows the ruler's units, and what rides an actor follows its root generators in games."]},{"version":"0.10.0","date":"2026-10-18","name":"Follow anchor and camera blends","Notes":["**Scenes ride a moving anchor**: A scene played on a moving part or attachment rides it: the Anchor is followed every frame, for every player. FollowAnchor = false reads it once, as before.","**Camera blends**: A switch key's Blend glides into its shot from the camera before it (in Studio's look through too), and CameraBlendIn and CameraBlendOut glide from the player's camera into the scene and back."],"Improved":["**Warps, spawns and props cost much less in games**: Far ones pose less often, an attached prop poses with what it rides, and a looped scene reuses its spawned copies.","**Targets are read where they stand now**: A target the scene doesn't move, like a walking NPC or a player, is read where it stands now, so warps follow it and props stuck to it go with it.","**Far crowds look smoother**: On computers and consoles everything within 80 studs poses every frame, then 30, 20 and 12 times a second out to 320 studs and beyond, and level of detail starts at 64 actors on screen. Phones keep the lighter settings.","**The camera glides back to a moving player**: The camera's glide back after a scene follows the player's camera wherever the character went, even while it walks."],"Fixed":["**Per target volleys land on each target**: A Per target volley lands each copy on its own target in games and in Studio (they all flew to the first one).","**Dropped objects stay where they dropped**: In games a dropped object stays where it was when it dropped, even when the target or the anchor isn't where the stand-in was.","**Warps hand over to Attach and Detach keys**: A Motion Warp that ends on a target hands the actor over to an Attach or Detach key after it, so a sticky shot can drop later."]},{"version":"0.9.2","date":"2026-10-18","name":"Warp shape settings","Notes":["**Settings for each warp path shape**: Turns for a Spiral, and Zig-zags and Corner smoothing for a Zig-zag. Bake shape to keys follows them."],"Improved":[],"Fixed":["**Spawned actors no longer blink off**: A spawned actor's preview copy no longer blinks off at some playheads (in games, a spawn no longer copies an earlier copy).","**Redo brings back a camera added at view**: Redo brings back a camera added at view, with its preview camera."]},{"version":"0.9.1","date":"2026-10-18","name":"Lag fixes and virtual cameras","Notes":["**Cameras added at view are virtual**: They live in the scene's data, show as a temporary Camera while the scene is open, and leave nothing in your place when it closes. In games they drive the player's camera."],"Improved":["**Bending warps no longer slow Studio down**: A selected Motion Warp that bends joints no longer slows Studio down; its path follows a key drag with fewer points and draws exactly again when you stop.","**Smoother key drags in the curve editor**: Dragging many keys in the curve editor is much smoother. Past 500 keys the curves follow the drag and the rest catches up when you let go.","**Less work every frame**: Scrubbing, playback, posing and the idle viewport do less work every frame, most of all in big scenes and with a motion trail, onion skins or drivers on.","**Warps and props cost less in games**: Motion Warps and attached props cost less to play in games."],"Fixed":[]},{"version":"0.9.0","date":"2026-10-17","name":"Motion Warp, holds and Repeat","Notes":["**Motion Warp**: Animate a trip once against the stand-ins and it lands on the real target in games, wherever that is. Add it from an actor, root or joint row.","**Path shapes**: Lob, High arc, Spiral, Zig-zag and Straight fly live, and Bake shape to keys writes one into keys. Click the curve's diamond for its arrow (Arc) and drag the diamond along its circle (Arc turn).","**Ease a trip**: Select a Motion Warp bar and press E. Timed By speed, a far target takes longer and what comes after waits.","**Bends reach the target**: A warp can bend a rig's joints so a hand, a claw or a head reaches the target, or bend the path and the joints together.","**Repeat a spawned actor**: One copy per target in a game list, or a count spread round an axis or at random, with a stagger.","**Hit-stop**: A marker's Hold freezes the scene (or one actor) for a few frames, with an optional camera kick.","**Overshoot / Settle and Stepped generators**: New generators: Overshoot / Settle and Stepped. The Library has a Warps tab of presets.","**Spread works on whole actors**: Spread a column of main keys to offset each actor's keys, blocks and markers."],"Improved":["**Guides drawn like the gizmo**: Viewport guides, motion trails, camera frustums and bones draw like the posing gizmo, solid and easy to see.","**Joint rows show their part's properties**: Selecting a joint row shows that part's properties; the root row shows the root part. Instance attributes show in the Inspector.","**Cameras added at view get a shot**: Adding a camera at view puts its shot on the Camera row, and right clicking the Camera row can remove it.","**The toolbar keeps to two rows**: The Timeline toolbar keeps to two rows when it fits."],"Fixed":["**Box select picks keys on block settings**: Box select picks up keys on a block's setting rows, and clicking one shows its block in the Inspector at that setting."]},{"version":"0.8.0","date":"2026-10-17","name":"Drivers and a faster Timeline","Notes":["**Drivers**: Set a property, a joint or one of its axes from something else. Copy a property, or map a distance, an axis, a speed or a property onto it, with a shape, a clamp and Smooth.","**Driver panel with Capture and a mapping graph**: A driver's Inspector panel has Capture buttons for its ranges and a mapping graph you can drag. Add a driver from a row, a lane or a property, or copy a property and Paste as driver.","**Copy drivers copy a pose or placement**: Copy drivers on joints copy a pose or a placement, all of it or the axes you tick.","**Colour ramps, custom drivers and presets**: Colour ramps, viewport guides, custom driver modules tagged AcesMotionDriver, presets and the Library's Drivers tab.","**Group key bars for crowded keys**: Keys too close to tell apart draw as one group key bar, and stacked main keys draw as an amber bar. Zoom in and they split."],"Improved":["**Big scenes stay smooth**: Thousands of keys, key groups and blocks pan, zoom, scroll, select and drag at full speed. Moving more than 500 keys or blocks slides them on the Timeline and applies the move when you let go.","**Lighter posing with the trail on**: Posing in FK and IK with the motion trail on is much lighter.","**Time fields follow the ruler**: Time fields in the Inspector and the Hub follow the ruler: seconds when it shows seconds, frames when it shows frames.","**Main keys and group keys renamed**: The amber triangle on an actor's row is now called a main key. A group key is the bar of keys that act as one.","**The Hub opens taller**"],"Fixed":["**Selected constraints show their guide**: Selecting a constraint on the Timeline shows its viewport guide."]},{"version":"0.7.1","date":"2026-10-16","name":"Full changelog and Settings fixes","Notes":["**The full changelog in Settings**: Settings > About shows the full changelog, every release, under its buttons.","**Settings from the Open a scene card**: A Settings button on the Open a scene card, so Settings is one click away with no scene open."],"Improved":["**Update checks every 30 minutes**: Studio checks for updates every 30 minutes while it stays open, and notes a new version in Output too.","**Settings fits a larger UI size**: The page list scrolls, and a setting's control moves under its name when the row is too narrow."],"Fixed":["**Synced runtimes no longer read as out of date**: A place whose runtime is synced from files no longer calls it out of date."]},{"version":"0.7.0","date":"2026-10-16","name":"Settings pages","Notes":["**The first team release**: On the Creator Store. Studio tells you when an update is out.","**Export settings**: Settings > Export: the export options every scene starts from.","**Versions settings**: Settings > Versions: turn the update check and What's new on or off.","**Timeline settings**: Settings > Timeline: the frame rate new scenes start at, row height, plain or typed key shapes, the playhead snapping to keys, and how fast the wheel scrolls rows.","**Audio settings**: Settings > Audio: how tall waveforms draw."],"Improved":["**A thousand props play at a fraction of the cost**: The parts a frame moves go in one bulk move."],"Fixed":[]},{"version":"0.6.5","date":"2026-10-16","name":"Smoother defaults","Notes":["**Level of detail only for crowds**: With up to 50 characters on screen, every one moves every frame. Past that, far ones step gently, more so the bigger the crowd."],"Improved":["**Nearby characters always move every frame**: Even when the frame budget is tight, and far ones never drop below 10 poses a second.","**A zoomed-in camera counts characters as closer**","**Crowds stay spread over frames after a hitch**: Characters stay spread over frames after a hitch, so a crowd doesn't stutter all at once."],"Fixed":[]},{"version":"0.6.4","date":"2026-10-16","name":"Level of detail for crowds","Notes":["**Level of detail in games**: Characters off screen stop posing and far ones pose less often, while their markers and events stay on time. A frame budget keeps crowds within a few milliseconds, lower on phones.","**The Important play option**: Keeps a hero, a boss or a close-up smooth at any distance."],"Improved":["**Crowds share their work**: Crowds playing the same scene share their work, and scenes with nothing to do skip whole frames."],"Fixed":[]},{"version":"0.6.3","date":"2026-10-16","name":"Client replication","Notes":["**Client-played emotes show for every player**: Emotes and moves played on a player's own character from their client show for every player, like Roblox's own animations. The server checks the player owns what they animate."],"Improved":["**The runtime plays scenes about four times faster**: With far less memory churn: crowds of NPCs, cutscenes and emotes all cost less each frame."],"Fixed":[]},{"version":"0.6.2","date":"2026-10-16","name":"The Ease window","Notes":["**The Ease window**: The ease popover is now a floating window that follows your key selection, with a foldable curve, the presets you used last and every preset one click away.","**Floor holds up any parts**: Floor on an actor's root row can hold up all its parts, its feet, hands, limbs or parts you pick, by lifting the actor or bending the limbs.","**Floor from a pivot or a bounding box**: Floor can measure from a part's pivot or its bounding box."],"Improved":["**The Timeline stays smooth with thousands of keys**: Dragging, selecting, panning, scrolling and zooming, in the dope sheet and the curve editor.","**Curve toolbar above the ruler**: The curve editor's toolbar sits above the ruler, next to the search row.","**Keyed properties sit under their joint**: A joint's keyed properties and generators sit right under its row.","**Guides only for selected constraints**: Constraint guides show only for the constraints selected on the Timeline, and the move, rotate and scale gizmo steps aside while they do.","**Submenus stay open while you move to them**"],"Fixed":["**The Library scrolls straight away**: The Library sometimes wouldn't scroll until the pointer left the window.","**Curve keys stay on their curves while panning**: Curve editor keys drifted off their curves while panning up and down."]},{"version":"0.6.1","date":"2026-10-16","name":"The Hub","Notes":["**The Hub**: One window for Scenes, Cast, Layers, History, the Inspector and the Library."],"Improved":["**The Inspector lists a pick's properties first**: The actor sections come after them; a pick about the rig scrolls to them.","**Custom module edits show at once**: Editing a custom action, generator or constraint shows the change in Studio's preview at once.","**Icons draw for everyone**: Every image the plugin shows is public, so icons draw for everyone."],"Fixed":[]},{"version":"0.6.0","date":"2026-10-16","name":"Constraints","Notes":["**Constraints**: Track To, Damped Track, Locked Track, Copy Location, Copy Rotation, Copy Transforms, Limit Location, Limit Rotation, Limit Distance, Floor, Delay, Face Motion and Horizon Lock drive an actor's root or a rig's joints from other things, on top of their keys.","**Constraints stack with generators**: They sit on the same lanes as generators and stack with them in your order: a camera's shake rides on top of its tracking. Influence, fades and their settings are keyable.","**Adding one picks its target**: Adding one picks its target straight away (or uses what's selected), and spans your selected keys, or a camera's current shot.","**Pose under a constraint**: You edit the keys underneath and see the result. What it takes over greys out on the gizmo, and a Track To adds a Roll ring.","**Targets the game fills in**: The local player, the nearest player, the player's camera or a tagged object, with a badge on the actor. Point targets aim at a spot you place and key.","**Distance fade on every constraint**: Full strength close by, fading out further away.","**Viewport guides for constraints**: Viewport guides show what each constraint does, with handles to drag its limits, distances and fades.","**Space and Relative to**: Measure a constraint's limits and axes from what it hangs from, its rest pose or any object you pick.","**Bake to keys and the Stack section**: Bake to keys takes the constraints above it along, and asks first when it would freeze something live. The Inspector's Stack section lists a row's stack in order, drag to reorder.","**Constraint presets**: Look at player, Turret, Level horizon, Bank into turns, Echo and your own, in the Library's new Constraints tab and in preset files.","**Custom constraints**: ModuleScripts tagged AcesMotionConstraint, made from a typed template, live in Studio and in games.","**Constraints play in games and export**: The runtime plays constraints live in games, and export bakes them into Roblox animations."],"Improved":["**Fades on bars draw as one curve**","**Menus can show an icon on each item**"],"Fixed":[]},{"version":"0.5.0","date":"2026-10-15","name":"Property driven generators","Notes":["**Generators**: Shake, Wiggle, Oscillate, Flicker / Strobe / Pulse, Spin and Recoil drive any value live over a span, on top of its keys, as blocks on a Generators lane under the row they drive.","**Generators drive almost any value**: They drive numbers, vectors, GUI sizes and positions, colours, ranges, sequences, a rig's root and joints, and on/off values. Cycle / Flipbook steps through any list of values and Typewriter types out text.","**Blend modes, Influence and keyable settings**: Blend each one by Add, Multiply or Replace, with Influence and fades, and key its settings: they show as rows under the block.","**Camera shake in one click**: Add camera shake on a camera actor in one click. Bake to keys writes a generator's result as keys.","**Live generator preview**: The generator panel in the Inspector has a live preview: Shape or Result, drag it to change size and timing, Shift+drag for a second setting, and pin it while you scroll. Pop it out into the Generator window.","**Drive modes**: A colour along a gradient or in HSV, a number between Low and High, a position on an orbit, an on/off pattern, ranges and sequences moved, morphed or scrolled.","**Snap to Loop**: A generator's speed snaps to values that loop seamlessly over its block, and Fit to playback range puts the block on the loop.","**Hold the channels a generator leaves alone**: Hold a channel a generator leaves alone at a number you type, and key it (S value 1 shows a hue cycle at full colour).","**Generator presets and preset files**: Built-in ones, your own from any block, and the Library's Generators tab. Preset files share ease and generator presets and saved colours, gradients and sequences with your team.","**Custom generators**: ModuleScripts tagged AcesMotionGenerator, made from a typed template, live in Studio and in games.","**Generators play in games and export**: The runtime plays generators live, seeded so every player sees the same, and export bakes them into Roblox animations.","**Generator results in the curve editor**: The curve editor draws a generator's result faded over the keys it moves."],"Improved":["**Smoother playing, scrubbing and key dragging**: Much smoother playing, scrubbing and key dragging, above all with the Inspector open.","**Closed windows cost nothing**: Closed windows no longer cost any time while you edit."],"Fixed":[]},{"version":"0.4.0","date":"2026-10-14","name":"Scene audio lanes","Notes":["**Audio lanes**: The scene's own sounds (music, voice-over, ambience) on named lanes at the bottom of the Timeline, each with its own Mute, Lock and volume.","**Clips work like sound bars**: Move, copy, trim, fade with shapes, loop, stretch, stack, scrub and snap to peaks, and they move together with your keys.","**Add sounds as templates or by id**: Add a sound from the Explorer as a template (it keeps its volume and effects) or by its id, or add an empty clip and paste an id.","**Play a clip in 2D or 3D**: Play a clip flat in 2D or in 3D from any part in the cast.","**The clip panel in the Inspector**: Timing, sound, volume, speed, trims, loop, fades and position. Select a lane for its own panel.","**Audio lanes play in games**: The runtime plays audio lanes wherever the scene plays, starting partway on SetTime and late joins."],"Improved":["**Sound labels start after the fade in**: A sound bar's label starts after its fade in, so the fade line never crosses it."],"Fixed":["**Looped sounds play on every pass**: A sound at the start of a looped region plays on every pass, not only the first.","**Jumping back replays a finished sound**: Jumping back into a sound that already finished plays it again."]},{"version":"0.3.4","date":"2026-10-14","name":"Attach and Detach","Notes":["**Attach to**: Shift+G: a part, joint, bone or whole actor follows anything you click, from the playhead, keeping its place. The grip is saved, so re-posing the hand carries the sword.","**Detach**: Shift+Alt+G drops it where it is. A rig joint detaches straight off its rig too: the torso no longer moves the arm, and its Motor6D stays.","**Back to rig**: Shift+Alt+A snaps a joint back into place, eased over a Blend; Back to rig where it is rejoins it without a jump.","**Attached rows on the Timeline**: Attach, Detach and Back to rig keys with bands in the target's colour, menus, dragging, copying, and group keys that move them with the actor's other keys.","**The Attach panel and Attached section**: The Attach panel in the Inspector works at the playhead like a property row, and every attached part shows an Attached section with its state and buttons.","**Attach to picking shows what you hover**: Attach to picking highlights what you hover, draws a line to it and names it; the gizmo hides while you pick.","**Moves by one of its parts**: A Model actor can move by one of its parts, so other designs with a part of the same name line up in game.","**IK through held objects**: With IK on, dragging something a hand holds moves the arm. FK adjusts the grip instead.","**Clicking a welded part picks its joint**: Clicking a welded part (an accessory, a held tool) picks the joint it's welded to. Pick welded parts turns this off.","**Attachments bake and play**: Attached joints bake into Roblox animations, and the runtime plays every attachment.","**Root rows and Unkeyed joints**: Rigs always show a root row to key where the whole rig stands. Unkeyed joints (off by default) lists every joint as a row, keyed or not."],"Improved":["**Joint rows follow the rig**: Parents before children.","**Key every joint at once**: Shift+K or a double click on a rig's row keys every joint, even ones not keyed yet.","**Copy is Shift+C everywhere**: Keys, poses, property values."],"Fixed":[]},{"version":"0.3.3","date":"2026-10-14","name":"Camera actors","Notes":["**Camera actors**: A frustum you pose with the gizmo like any actor; drag its blue dot or scale it on Z to change FieldOfView.","**Several cameras per scene**: Switched by keys on the Camera track at the top of the Timeline. The same switches play in game.","**Look through the live camera**: Press Q. Move the view while paused to look away; scrub or play to snap back.","**Pilot camera**: Ctrl+Shift+Q: fly Studio's view to move the camera you look through, keyed with auto-key.","**Point a camera at what you hover**: F turns a picked camera to look at what is under the mouse; Ctrl+F also levels its roll.","**Spawned actors act like real actors**: A live copy is their stand-in, with their own Spawn row, Appear and Disappear keys, Parent to, Linger and Save look to template.","**The Hub**: The Hub is one window with Inspector and Library tabs that pop out, reorder and keep their order.","**Actor markers**: Actor markers on an actor's row, and markers on one frame sit side by side.","**Key groups**: Group a row's keys into one bar that moves, copies and retimes as one.","**Convert to a spawned actor and back**","**Fit to a sound, region from keys**: Fit scene length to a sound, and set the loop or export region from selected keys.","**Search in Shortcuts**: Search in Settings > Shortcuts.","**The empty Timeline lists scenes**: The empty Timeline lists the place's scenes.","**A notice for runtime-only features**: A one-time notice when a scene uses features that need the runtime, plus an amber Runtime chip in the status bar.","**Toolbar layout**: Two rows or One row, wrapping by width, with a More menu for what doesn't fit."],"Improved":["**Bars re-measure when properties change**: A sound's or emitter's bars re-measure when its properties change.","**Mute or lock several rows at once**: Select several rows and mute or lock them all at once.","**Shift+Left and Shift+Right nudge keys**: Shift+Left and Shift+Right nudge selected keys.","**Ease presets apply to the sequence editor**: Library ease presets apply to the open sequence editor.","**Copy and paste property values**: Copy and paste property values between Inspector rows.","**Region handles light up on hover**"],"Fixed":["**The Easing tab scrolls to the end**: The Library's Easing tab scrolls to its last sections.","**The sequence editor opens tall enough**: The sequence editor opens tall enough to use."]},{"version":"0.3.2","date":"2026-10-10","name":"Inspector for blocks and markers","Notes":["**Edit action blocks in the Inspector**: Select an action block to edit its timing, every parameter its module declares (with each param's description as a tooltip), and its module with Open script and Select in Explorer.","**New parameter pickers**: Actor, ActorPart (anything inside an actor, from a searchable list or by clicking it in the viewport or the Explorer), Joint, Template and Marker.","**Edit markers in the Inspector**: Select a marker to edit its name, frame, colour and payload in the Inspector. Markers also fire OnEvent.","**One payload table for events and markers**: Event blocks and markers share one payload table: named values of any type.","**The object list can start expanded**: Settings > Look: the object list can start expanded."],"Improved":["**One searchable dropdown**: The Inspector's object list and every picker share one searchable dropdown.","**Open script brings its tab forward**: Open script brings an already open script's tab to the front.","**Group keys redrawn**: Even spacing, and a clearer look when some of their keys are selected.","**Dashed marker lines above the grid**: Marker lines are dashed and always draw above the grid."],"Fixed":[]},{"version":"0.3.1","date":"2026-10-10","name":"Action tracks and blocks","Notes":["**Action tracks on the Timeline**: Event blocks and your own custom actions, as bars and chips you drag, trim, duplicate and delete.","**Custom actions**: ModuleScripts tagged AcesMotionAction, wherever you keep them. New custom action makes one from a commented template.","**Actions run in Studio's preview**: Actions run as you play and scrub, loaded fresh each run so your edits apply right away.","**Action code gets the scene's timing**: Action code gets the scene's time, frame, frame rate and speed, and can handle a cast change with Recast.","**Group keys include action blocks**: Group keys include action blocks, and are now amber triangles.","**Drag stacked bars between lanes**: Drag stacked sound, Emit and action bars up or down to choose their lane.","**Actions settings**: Settings > Actions."],"Improved":["**Blocks survive a renamed module**: Renaming or moving an action module keeps its blocks; Resolve target repairs a block whose module is gone."],"Fixed":[]},{"version":"0.3.0","date":"2026-10-10","name":"Property tracks","Notes":["**Animate any property**: The Inspector lists every property by category with editors, drag to scrub and key diamonds; values that can't blend show as bars on the Timeline.","**Properties window edits are keyed**: Edits in Studio's Properties window are keyed with auto-key on.","**Emit() and Play() keys**: Sound bars with waveforms, trims, fades, speed, loops, audio scrubbing and snapping to waveform peaks.","**Effect preview**: Particles show while you scrub, with burst and stream bars and lifetime grips.","**Resize tool**: Resize tool for parts and models, keyed as Size or Scale.","**Edit several objects at once**: Edit several objects at once in the Inspector.","**Colour, sequence and gradient editors**: Colour picker, sequence editor and gradient editor windows with presets, saved colours, gradients and sequences, and their own undo.","**Look, Shortcuts and Storage settings**: Settings: Look (accent colour, UI scale, tooltips), Shortcuts (every key, rebinding) and Storage pages; three icon styles.","**Crash recovery**: A recovered copy is offered when a scene opens."],"Improved":["**Add and remove actors from the Timeline**: Add or remove actors and remove several tracks at once from the Timeline.","**Taller sound and effect rows**: Drag the top or bottom of a sound or effect row to make it taller.","**Move and rotate follow Studio's stepping**: Move and rotate follow Studio's stepping settings."],"Fixed":[]},{"version":"0.2.0","date":"2026-10-09","name":"Posing, onion skin and curves","Notes":["**Posing**: AcesMotion's own gizmo, pins, context IK, joint limits, mirror rules, pose tools and flip.","**Onion skin and editable motion trails**: Onion skin and motion trails you can edit, with pen, timing and limbs only modes.","**Curve editor**: Channels and Ease views, split with the dope sheet, Euler filter and rotation modes.","**Ease tools**: The ease popover (E), spread, presets built on animation principles, saved presets and the Library Easing tab.","**Export several rigs at once**: Export several rigs at once, as Roblox animations or as runtime scenes, and pack scenes for other games.","**Reusable runtime tracks**: Load a track, tune it and play it again and again; change its cast and options while it plays.","**Scenes can live in any folder**"],"Improved":["**Errors stay contained**: Errors in one part of the plugin no longer break the rest."],"Fixed":[]},{"version":"0.1.0","date":"2026-10-08","name":"First release","Notes":["**Plugin shell**: Timeline, Hub, Inspector and Settings windows.","**A Studio themed look**: Studio themed look with tooltips on every button.","**Play scenes in games**: Play and PlayForAll, markers in server code, one click install."],"Improved":[],"Fixed":[]}]`),f=["id"],k={class:"am-release-date"},v=["href"],x=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1792713747000}'),b={name:"changelog.md"},S=Object.assign(b,{setup(A){const l={Notes:"New",Improved:"Improved",Fixed:"Fixed"};return(T,n)=>(t(),o("div",null,[n[0]||(n[0]=e("h1",{id:"changelog",tabindex:"-1"},[r("Changelog "),e("a",{class:"header-anchor",href:"#changelog","aria-label":'Permalink to "Changelog"'},"​")],-1)),n[1]||(n[1]=e("p",null,[r("What changed in each release, newest first. The same list is in the plugin under "),e("strong",null,"Settings > About"),r(".")],-1)),(t(!0),o(s,null,h(u(y),a=>(t(),o(s,{key:a.version},[e("h2",{id:"v"+a.version.replaceAll(".","-"),tabindex:"-1"},[r(i(a.version)+" ",1),e("span",k,i(a.date),1),e("a",{class:"header-anchor",href:"#v"+a.version.replaceAll(".","-"),"aria-hidden":"true"},null,8,v)],8,f),(t(),o(s,null,h(l,(c,d)=>(t(),o(s,{key:d},[a[d].length?(t(),o(s,{key:0},[e("h3",null,i(c),1),e("ul",null,[(t(!0),o(s,null,h(a[d],(p,m)=>(t(),o("li",{key:m},i(p),1))),128))])],64)):g("",!0)],64))),64))],64))),128))]))}}),I=w(S,[["__scopeId","data-v-98e4dac9"]]);export{x as __pageData,I as default};
